package proxy
import("context";"encoding/json";"fmt";"os";"os/exec";"path/filepath";"strings";"syscall";"testing";"time")
func TestChild(t *testing.T){root:=os.Getenv("ROOT");if root==""{t.Skip()};if e:=syscall.Chroot(root);e!=nil{t.Fatal(e)};if e:=os.Chdir("/");e!=nil{t.Fatal(e)};if e:=syscall.Setuid(65534);e!=nil{t.Fatal(e)};fmt.Printf("ROW %s\n",detectProxyMode())}
func TestCapture(t *testing.T){rows:=[]string{};for _,name:=range []string{"absent","present","unreadable"}{root,e:=os.MkdirTemp("/tmp","proxy-");if e!=nil{t.Fatal(e)};if e=os.Chmod(root,0755);e!=nil{t.Fatal(e)};dir:=filepath.Join(root,"proc/net");if e=os.MkdirAll(dir,0755);e!=nil{t.Fatal(e)};if name!="absent"{if e=os.WriteFile(dir+"/ip_tables_names",nil,0444);e!=nil{t.Fatal(e)}};if name=="unreadable"{if e=os.Chmod(dir,0000);e!=nil{t.Fatal(e)}}
 ctx,cancel:=context.WithTimeout(context.Background(),5*time.Second);cmd:=exec.CommandContext(ctx,os.Args[0],"-test.run=^TestChild$","-test.v");cmd.Env=[]string{"ROOT="+root};out,e:=cmd.CombinedOutput();cancel();if e!=nil{t.Fatalf("%v %s",e,out)};found:=0;for _,line:=range strings.Split(string(out),"\n"){if strings.HasPrefix(line,"ROW "){rows=append(rows,name+"\t"+strings.TrimPrefix(line,"ROW "));found++}};if found!=1{t.Fatal("count")};if e=os.Chmod(dir,0755);e!=nil{t.Fatal(e)};if e=os.RemoveAll(root);e!=nil{t.Fatal(e)}};data,e:=json.Marshal(rows);if e!=nil{t.Fatal(e)};fmt.Printf("RUBIX_CAPTURE %s\n",data)}
